export function formatCurrency(value: number): string {
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(value);
}

export function formatNumber(value: number): string {
  return new Intl.NumberFormat('pt-BR').format(value);
}

export function getKPIs(data: Edital[]) {
  const captados = data.length;
  const participados = data.filter(e => ['VENCEU', 'PERDEU', 'AGUARDANDO RESULTADO', 'EM ANDAMENTO'].includes(e.participou)).length;
  const decididos = data.filter(e => ['VENCEU', 'PERDEU'].includes(e.participou)).length;
  const vencidos = data.filter(e => e.participou === 'VENCEU').length;
  const taxaVitoria = decididos > 0 ? (vencidos / decididos) * 100 : 0;
  const valorEstimadoTotal = data.reduce((sum, e) => sum + (e.valorEstimado ?? 0), 0);
  const valorGanho = data.filter(e => e.participou === 'VENCEU').reduce((sum, e) => sum + (e.valorFechado ?? e.valorEstimado ?? 0), 0);
  const perdidos = data.filter(e => e.participou === 'PERDEU');
  const valorPerdidoCaptado = perdidos.reduce((sum, e) => sum + (e.valorEstimado ?? 0), 0);
  const valorPerdidoFechado = perdidos.reduce((sum, e) => sum + (e.valorFechado ?? 0), 0);
  const valorPerdido = valorPerdidoFechado;
  const taxaParticipacao = captados > 0 ? (participados / captados) * 100 : 0;

  return { captados, participados, decididos, vencidos, taxaVitoria, valorEstimadoTotal, valorGanho, valorPerdido, valorPerdidoCaptado, valorPerdidoFechado, taxaParticipacao };
}
